import{_ as a,c as s,o as n,a0 as t}from"./chunks/framework.C1J0Vcxi.js";const h=JSON.parse('{"title":"共享系统栈","description":"","frontmatter":{"title":"共享系统栈","date":"2026-05-09T00:00:00.000Z","type":"description"},"headers":[],"relativePath":"docs/shared-stack.md","filePath":"docs/shared-stack.md"}'),c={name:"docs/shared-stack.md"};function o(p,e,r,l,i,d){return n(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="共享系统栈" tabindex="-1">共享系统栈 <a class="header-anchor" href="#共享系统栈" aria-label="Permalink to &quot;共享系统栈&quot;">​</a></h1><p>RT-Async 最核心的设计：所有 executor 共用同一个系统栈，不逐 executor 分配独立栈空间。</p><h2 id="原理" tabindex="-1">原理 <a class="header-anchor" href="#原理" aria-label="Permalink to &quot;原理&quot;">​</a></h2><p>传统 RTOS 为每个线程分配独立栈，栈切换通过保存/恢复全部 callee-saved 寄存器完成（汇编上下文切换）。RT-Async 的 executor 切换复用 Rust 的函数调用/返回语义：</p><ul><li><strong>抢占</strong> = 在被抢占 executor 的栈帧之上调用新 executor 的 <code>run()</code>（像嵌套函数调用）</li><li><strong>返回</strong> = executor <code>run()</code> 返回，栈帧自然销毁，SP 回退</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>时间线 →</span></span>
<span class="line"><span></span></span>
<span class="line"><span>栈空间     ┌─────────────┐</span></span>
<span class="line"><span>  ↑        │  Executor C  │  ← 抢占 B 后运行</span></span>
<span class="line"><span>  │        ├─────────────┤</span></span>
<span class="line"><span>  │        │  Executor B  │  ← 抢占 A 后运行</span></span>
<span class="line"><span>  │        ├─────────────┤</span></span>
<span class="line"><span>  │        │  Executor A  │  ← 最初运行</span></span>
<span class="line"><span>  │        ├─────────────┤</span></span>
<span class="line"><span>  │        │  空闲        │</span></span>
<span class="line"><span>            └─────────────┘</span></span></code></pre></div><h2 id="prio-stack" tabindex="-1">prio_stack <a class="header-anchor" href="#prio-stack" aria-label="Permalink to &quot;prio_stack&quot;">​</a></h2><p><code>Spawner</code> 内部维护一个 LIFO 优先级栈（<code>heapless::Vec&lt;Priority, N&gt;</code>），记录哪些 executor 当前占据系统栈空间：</p><ul><li><code>try_preempt()</code> → 读栈顶作为当前优先级 → 若有更高就绪，push 新优先级到栈顶</li><li><code>run()</code> 返回后 → <code>complete_executor()</code> → pop 栈顶</li></ul><p>栈顶始终是当前运行的 executor 的优先级。</p><h2 id="零额外栈切换开销" tabindex="-1">零额外栈切换开销 <a class="header-anchor" href="#零额外栈切换开销" aria-label="Permalink to &quot;零额外栈切换开销&quot;">​</a></h2><p>executor 切换不需要保存/恢复 callee-saved 寄存器组。切换过程完全由 Pend ISR 中的 <code>save callee-saved regs</code> / <code>restore callee-saved regs</code> 完成——这是唯一需要汇编的地方，且只在 ISR 入口/出口各执行一次，不随 executor 嵌套深度增加。</p><p>嵌套的 executor 直接在栈上增长，自然受到系统栈大小的约束。系统栈需要预留足够空间以容纳最深的嵌套场景。</p><h2 id="任务数量无上限" tabindex="-1">任务数量无上限 <a class="header-anchor" href="#任务数量无上限" aria-label="Permalink to &quot;任务数量无上限&quot;">​</a></h2><p>传统 RTOS 的任务数量受限于预先分配的栈数量。RT-Async 中任务不拥有独立栈——它们共享所属 executor 的调用栈。栈空间由 executor 的调用链（<code>run()</code> → poll Future → <code>.await</code>）动态分配，与任务数量无关。</p>`,15)])])}const x=a(c,[["render",o]]);export{h as __pageData,x as default};
